mapper.select:
SELECT * FROM blog_page_view

    AND visitor_id=#{visitor}AND user_id=#{user}AND article_id=#{article}
    AND site_code=#{query.siteCode}AND page_path=#{query.pagePath}
    AND INSTR(referer,#{query.referer}) > 0
    AND view_time >= #{begin}AND view_time < #{end}

ORDER BY view_time DESC,view_id DESC
